/**
 * AI assistant admin API.
 *
 * Provides:
 *   GET  /ai/config         - read current ai settings (apiKey masked)
 *   POST /ai/config         - update ai settings (provider/baseUrl/apiKey/model)
 *   POST /ai/chat           - forward a chat request to the configured provider
 *   POST /ai/parse-protocol - upload a protocol document and let the model
 *                             extract a normalised description (properties,
 *                             methods, codec). Phase 1 only returns the
 *                             structured description; flow generation lives
 *                             in a later phase.
 *
 * The api key is persisted on disk under <userDir>/ai-config.json with a
 * lightweight obfuscation. It is never returned to the client; clients only
 * ever receive a boolean `hasApiKey` flag plus a short suffix for hint.
 */

var fs = require("fs");
var path = require("path");
var crypto = require("crypto");
var https = require("https");
var http = require("http");
var url = require("url");
var os = require("os");
var child_process = require("child_process");
var docParser = require("./doc-parser");

var hooks;
try { hooks = require("@node-red/util").hooks; } catch (e) { hooks = null; }

function summarisePayload(value, depth) {
    if (depth === undefined) { depth = 0; }
    if (depth > 3) { return "[depth-limit]"; }
    if (value === null || value === undefined) { return value; }
    var t = typeof value;
    if (t === "string") {
        return value.length > 400 ? value.slice(0, 400) + "…(+" + (value.length - 400) + ")" : value;
    }
    if (t === "number" || t === "boolean") { return value; }
    if (t === "function") { return "[function]"; }
    if (Buffer.isBuffer(value)) { return "[Buffer " + value.length + "B]"; }
    if (Array.isArray(value)) {
        return value.slice(0, 20).map(function (v) { return summarisePayload(v, depth + 1); });
    }
    if (t === "object") {
        var out = {};
        var keys = Object.keys(value).slice(0, 30);
        keys.forEach(function (k) {
            if (k === "_msgid" || k === "_session") { return; }
            try { out[k] = summarisePayload(value[k], depth + 1); }
            catch (e) { out[k] = "[unserialisable]"; }
        });
        return out;
    }
    return String(value);
}

function summariseMsg(msg) {
    if (!msg || typeof msg !== "object") { return summarisePayload(msg); }
    var out = {};
    Object.keys(msg).forEach(function (k) {
        if (k === "_msgid" || k === "_session") { return; }
        out[k] = summarisePayload(msg[k]);
    });
    return out;
}

var tapSessionCounter = 0;

function tapNodes(opts) {
    if (!hooks || typeof hooks.add !== "function") {
        return Promise.reject(new Error("runtime hooks API not available"));
    }
    var nodeIds = Array.isArray(opts.nodeIds) ? opts.nodeIds.filter(Boolean) : [];
    if (!nodeIds.length) { return Promise.reject(new Error("nodeIds required")); }
    var maxMessages = Math.max(1, Math.min(parseInt(opts.maxMessages, 10) || 10, 50));
    var durationMs = Math.max(500, Math.min(parseInt(opts.durationMs, 10) || 5000, 30000));
    var idSet = new Set(nodeIds);
    var captured = [];
    var label = "ai-tap-" + (++tapSessionCounter) + "-" + Date.now();

    return new Promise(function (resolve) {
        var done = false;
        var finish = function () {
            if (done) { return; }
            done = true;
            try { hooks.remove(label); } catch (e) {}
            resolve({
                ok: true,
                durationMs: durationMs,
                requested: nodeIds,
                captured: captured.length,
                events: captured
            });
        };

        hooks.add("onSend." + label, function (sendEvents) {
            if (done) { return; }
            if (!Array.isArray(sendEvents)) { return; }
            sendEvents.forEach(function (evt) {
                var sourceId = evt && evt.source && evt.source.node && evt.source.node.id;
                if (!sourceId || !idSet.has(sourceId)) { return; }
                if (captured.length >= maxMessages) { return; }
                var port = evt.source.port;
                var msg = evt.msg;
                captured.push({
                    nodeId: sourceId,
                    port: typeof port === "number" ? port : 0,
                    ts: new Date().toISOString(),
                    msg: summariseMsg(msg)
                });
                if (captured.length >= maxMessages) { setImmediate(finish); }
            });
        });
        setTimeout(finish, durationMs);
    });
}


var settings;
var configPath;
var configCache;

var SCRAMBLE_KEY = "node-red-ai-assistant-v1";

function scramble(plain) {
    if (!plain) { return ""; }
    var key = crypto.createHash("sha256").update(SCRAMBLE_KEY).digest();
    var iv = crypto.randomBytes(12);
    var cipher = crypto.createCipheriv("aes-256-gcm", key, iv);
    var enc = Buffer.concat([cipher.update(plain, "utf8"), cipher.final()]);
    var tag = cipher.getAuthTag();
    return "v1:" + iv.toString("base64") + ":" + tag.toString("base64") + ":" + enc.toString("base64");
}

function unscramble(blob) {
    if (!blob || typeof blob !== "string" || blob.indexOf("v1:") !== 0) {
        return "";
    }
    var parts = blob.split(":");
    if (parts.length !== 4) { return ""; }
    var key = crypto.createHash("sha256").update(SCRAMBLE_KEY).digest();
    var iv = Buffer.from(parts[1], "base64");
    var tag = Buffer.from(parts[2], "base64");
    var enc = Buffer.from(parts[3], "base64");
    try {
        var decipher = crypto.createDecipheriv("aes-256-gcm", key, iv);
        decipher.setAuthTag(tag);
        return Buffer.concat([decipher.update(enc), decipher.final()]).toString("utf8");
    } catch (err) {
        return "";
    }
}

function loadConfig() {
    if (configCache) { return configCache; }
    try {
        var raw = fs.readFileSync(configPath, "utf8");
        configCache = JSON.parse(raw);
    } catch (err) {
        configCache = {};
    }
    return configCache;
}

function saveConfig(cfg) {
    configCache = cfg;
    try {
        fs.writeFileSync(configPath, JSON.stringify(cfg, null, 2), { mode: 0o600 });
    } catch (err) {
        // surfaced to caller via outer try/catch
        throw err;
    }
}

function maskedConfig() {
    var cfg = loadConfig();
    var apiKey = unscramble(cfg.apiKey || "");
    var hint = "";
    if (apiKey && apiKey.length > 4) {
        hint = "****" + apiKey.slice(-4);
    } else if (apiKey) {
        hint = "****";
    }
    return {
        provider: cfg.provider || "openai",
        baseUrl: cfg.baseUrl || "",
        model: cfg.model || "",
        hasApiKey: !!apiKey,
        apiKeyHint: hint,
        searchEnabled: (cfg.search || {}).enabled === true,
        searchApiUrl: (cfg.search || {}).apiUrl || "",
        searchEngine: (cfg.search || {}).engine || "google",
        searchApiKeyHint: (function() {
            var sak = unscramble((cfg.search || {}).apiKey || "");
            if (sak && sak.length > 4) { return "****" + sak.slice(-4); }
            if (sak) { return "****"; }
            return "";
        })()
    };
}

function getResolvedConfig() {
    var cfg = loadConfig();
    return {
        provider: cfg.provider || "openai",
        baseUrl: cfg.baseUrl || "",
        model: cfg.model || "",
        apiKey: unscramble(cfg.apiKey || "")
    };
}

function getSearchConfig() {
    var cfg = loadConfig();
    var search = cfg.search || {};
    return {
        enabled: search.enabled === true,
        apiUrl: search.apiUrl || "",
        apiKey: unscramble(search.apiKey || ""),
        engine: search.engine || "google"
    };
}

function httpRequest(targetUrl, method, headers, body) {
    return new Promise(function(resolve, reject) {
        var parsed = url.parse(targetUrl);
        var lib = parsed.protocol === "http:" ? http : https;
        var bodyBuffer = body ? Buffer.from(body, "utf8") : null;
        var reqHeaders = Object.assign({}, headers || {});
        if (bodyBuffer) {
            reqHeaders["Content-Length"] = bodyBuffer.length;
        }
        var req = lib.request({
            method: method,
            protocol: parsed.protocol,
            hostname: parsed.hostname,
            port: parsed.port,
            path: parsed.path,
            headers: reqHeaders
        }, function(res) {
            var chunks = [];
            res.on("data", function(c) { chunks.push(c); });
            res.on("end", function() {
                var text = Buffer.concat(chunks).toString("utf8");
                resolve({ status: res.statusCode, body: text, headers: res.headers });
            });
        });
        req.on("error", reject);
        if (bodyBuffer) { req.write(bodyBuffer); }
        req.end();
    });
}

function callOpenAICompatible(cfg, messages, opts) {
    var baseUrl = (cfg.baseUrl || "https://api.openai.com").replace(/\/$/, "");
    var endpoint = baseUrl + "/v1/chat/completions";
    var converted = messages.map(function (m) {
        if (m.role === "tool") {
            return { role: "tool", tool_call_id: m.toolCallId, content: typeof m.content === "string" ? m.content : JSON.stringify(m.content) };
        }
        if (m.role === "assistant" && Array.isArray(m.toolCalls) && m.toolCalls.length) {
            return {
                role: "assistant",
                content: m.content || null,
                tool_calls: m.toolCalls.map(function (tc) {
                    return { id: tc.id, type: "function", function: { name: tc.name, arguments: JSON.stringify(tc.arguments || {}) } };
                })
            };
        }
        return { role: m.role, content: m.content };
    });
    var payload = {
        model: cfg.model || "gpt-4o-mini",
        messages: converted,
        temperature: (opts && typeof opts.temperature === "number") ? opts.temperature : 0.3,
        stream: false
    };
    if (opts && opts.responseFormat === "json") {
        payload.response_format = { type: "json_object" };
    }
    if (opts && Array.isArray(opts.tools) && opts.tools.length) {
        payload.tools = opts.tools.map(function (t) {
            return {
                type: "function",
                function: {
                    name: t.name,
                    description: t.description,
                    parameters: t.parameters || { type: "object", properties: {} }
                }
            };
        });
        payload.tool_choice = "auto";
    }
    return httpRequest(endpoint, "POST", {
        "Content-Type": "application/json",
        "Authorization": "Bearer " + cfg.apiKey
    }, JSON.stringify(payload)).then(function(res) {
        if (res.status < 200 || res.status >= 300) {
            var msg = "provider returned " + res.status;
            try { msg += ": " + JSON.parse(res.body).error.message; } catch (e) {}
            var err = new Error(msg);
            err.status = res.status;
            throw err;
        }
        var data = JSON.parse(res.body);
        var choice = data.choices && data.choices[0];
        var msgObj = choice && choice.message || {};
        var toolCalls = [];
        if (Array.isArray(msgObj.tool_calls)) {
            toolCalls = msgObj.tool_calls.map(function (tc) {
                var args = {};
                try { args = JSON.parse(tc.function.arguments || "{}"); } catch (e) { args = { _raw: tc.function.arguments }; }
                return { id: tc.id, name: tc.function.name, arguments: args };
            });
        }
        return {
            content: msgObj.content || "",
            toolCalls: toolCalls,
            finishReason: choice && choice.finish_reason || null,
            usage: data.usage || null,
            raw: data
        };
    });
}

function callAnthropic(cfg, messages, opts) {
    var baseUrl = (cfg.baseUrl || "https://api.anthropic.com").replace(/\/$/, "");
    var endpoint = baseUrl + "/v1/messages";
    var systemPrompt = "";
    var converted = [];
    messages.forEach(function(m) {
        if (m.role === "system") {
            systemPrompt += (systemPrompt ? "\n\n" : "") + (typeof m.content === "string" ? m.content : "");
            return;
        }
        if (m.role === "tool") {
            converted.push({
                role: "user",
                content: [{ type: "tool_result", tool_use_id: m.toolCallId, content: typeof m.content === "string" ? m.content : JSON.stringify(m.content) }]
            });
            return;
        }
        if (m.role === "assistant" && Array.isArray(m.toolCalls) && m.toolCalls.length) {
            var blocks = [];
            if (m.content) { blocks.push({ type: "text", text: m.content }); }
            m.toolCalls.forEach(function (tc) {
                blocks.push({ type: "tool_use", id: tc.id, name: tc.name, input: tc.arguments || {} });
            });
            converted.push({ role: "assistant", content: blocks });
            return;
        }
        converted.push({ role: m.role, content: m.content });
    });
    var payload = {
        model: cfg.model || "claude-sonnet-4-6",
        max_tokens: (opts && opts.maxTokens) || 4096,
        temperature: (opts && typeof opts.temperature === "number") ? opts.temperature : 0.3,
        messages: converted
    };
    if (systemPrompt) { payload.system = systemPrompt; }
    if (opts && Array.isArray(opts.tools) && opts.tools.length) {
        payload.tools = opts.tools.map(function (t) {
            return {
                name: t.name,
                description: t.description,
                input_schema: t.parameters || { type: "object", properties: {} }
            };
        });
    }
    return httpRequest(endpoint, "POST", {
        "Content-Type": "application/json",
        "x-api-key": cfg.apiKey,
        "anthropic-version": "2023-06-01"
    }, JSON.stringify(payload)).then(function(res) {
        if (res.status < 200 || res.status >= 300) {
            var msg = "provider returned " + res.status;
            try { msg += ": " + JSON.parse(res.body).error.message; } catch (e) {}
            var err = new Error(msg);
            err.status = res.status;
            throw err;
        }
        var data = JSON.parse(res.body);
        var content = "";
        var toolCalls = [];
        if (Array.isArray(data.content)) {
            data.content.forEach(function(block) {
                if (block.type === "text") { content += block.text; }
                else if (block.type === "tool_use") {
                    toolCalls.push({ id: block.id, name: block.name, arguments: block.input || {} });
                }
            });
        }
        return {
            content: content,
            toolCalls: toolCalls,
            finishReason: data.stop_reason || null,
            usage: data.usage || null,
            raw: data
        };
    });
}

function callProvider(cfg, messages, opts) {
    if (!cfg.apiKey) {
        return Promise.reject(Object.assign(new Error("AI api key is not configured"), { status: 400 }));
    }
    if (cfg.provider === "anthropic") {
        return callAnthropic(cfg, messages, opts);
    }
    return callOpenAICompatible(cfg, messages, opts);
}

